// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The jobs of JobBoard as cards in two columns (title, department, place, type, optional salary, posted, apply)
 * or as a table.
 */
import { For, type JSX } from "solid-js";
import { Badge, Box, Grid, Group, Inline, Stack, Table, TableBody, TableCaption, TableCell, TableHead, TableHeadCell, TableRow, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { MenuEntry } from "../components/menu-entry";
import type { Job, Department, JobLabels } from "../blocks/job-board.types";

export type JobCardsProps = {
  jobs: Job[];
  departments: Department[];
  labels: JobLabels;
  layout?: "grid" | "grouped" | "table";
  salary?: "show" | "hide";
};

export function JobCards({ jobs, departments, labels, layout = "grid", salary = "hide" }: JobCardsProps) {
  return (
    <>
      {((layout as string) === "table") ? (
        <Box class="w-full overflow-x-auto rounded inset-ring inset-ring-border" data-slot="job-cards">
          <Table class="w-full text-left text-sm" data-slot="job-table">
            <TableCaption class="sr-only">
              {labels.caption}
            </TableCaption>
            <TableHead class="bg-muted">
              <TableRow>
                <TableHeadCell scope="col" class="px-4 py-2">
                  {labels.role}
                </TableHeadCell>
                <TableHeadCell scope="col" class="hidden py-2 md:table-cell">
                  {labels.team}
                </TableHeadCell>
                <TableHeadCell scope="col" class="hidden py-2 sm:table-cell">
                  {labels.location}
                </TableHeadCell>
                <TableHeadCell scope="col" class="py-2">
                  {labels.type}
                </TableHeadCell>
                {((salary as string) === "show") ? (
                  <TableHeadCell scope="col" class="hidden py-2 md:table-cell">
                    {labels.salary}
                  </TableHeadCell>
                ) : null}
                <TableHeadCell scope="col" class="py-2 pr-4">
                  <Inline class="sr-only">
                    {labels.apply}
                  </Inline>
                </TableHeadCell>
              </TableRow>
            </TableHead>
            <TableBody>
              <For each={jobs ?? []}>{(j) => (
                <TableRow class="border-t border-border" data-slot="item">
                  <TableCell class="px-4 py-4 font-medium">
                    {j.title}
                  </TableCell>
                  <TableCell class="hidden md:table-cell">
                    {departments.filter((i) => !j.dept || i["id"] === j.dept)[0]?.name ?? ""}
                  </TableCell>
                  <TableCell class="hidden sm:table-cell">
                    {j.location}
                  </TableCell>
                  <TableCell>
                    {j.type}
                  </TableCell>
                  {((salary as string) === "show") ? (
                    <TableCell class="hidden md:table-cell">
                      {j.salary}
                    </TableCell>
                  ) : null}
                  <TableCell class="pr-4 text-right">
                    <MenuEntry href={j.href} class="font-medium">
                      {labels.apply}
                    </MenuEntry>
                  </TableCell>
                </TableRow>
              )}</For>
            </TableBody>
          </Table>
        </Box>
      ) : (
        <Grid cols="1-2" class="gap-4" data-slot="items">
          <For each={jobs ?? []}>{(j) => (
            <Stack gap="4" class="rounded bg-card inset-ring inset-ring-border p-6" data-slot="item">
              <Stack gap="2">
                <Text size="lg" weight="semibold">
                  {j.title}
                </Text>
                <Group gap="4" class="flex-wrap text-sm text-muted-foreground">
                  <Group gap="2" align="center">
                    <LucideIcon name="briefcase" size={16} />
                    <Inline>
                      {j.type}
                    </Inline>
                  </Group>
                  <Group gap="2" align="center">
                    <LucideIcon name="map-pin" size={16} />
                    <Inline>
                      {j.location}
                    </Inline>
                  </Group>
                  <Group gap="2" align="center">
                    <LucideIcon name="calendar" size={16} />
                    <Inline>
                      {j.posted}
                    </Inline>
                  </Group>
                </Group>
              </Stack>
              {((salary as string) === "show") ? (
                <Text size="base" weight="semibold" data-slot="salary">
                  {j.salary}
                </Text>
              ) : null}
              <Group gap="4" align="center" justify="between" class="mt-auto">
                <Badge variant="secondary" size="default">
                  {departments.filter((i) => !j.dept || i["id"] === j.dept)[0]?.name ?? ""}
                </Badge>
                <MenuEntry href={j.href} class="inline-flex items-center gap-2 text-sm font-medium">
                  {labels.apply}
                  <LucideIcon name="arrow-right" size={16} />
                </MenuEntry>
              </Group>
            </Stack>
          )}</For>
        </Grid>
      )}
    </>
  );
}
